#include <cmath>
#include <algorithm>
#include <vector>
extern \"C\" void all_dtw(const double* S, int n, int m, double* out) {
 const double neg=-1e9; const double penalty=.035;
 std::vector<double> D((n+1)*(m+1));
 for(int s=1;s<n-4;s++){
  std::fill(D.begin(),D.end(),neg);D[s*(m+1)]=0;
  for(int i=s+1;i<=std::min(n-1,s+40);i++){
   for(int j=1;j<=m;j++){
    double v=D[(i-1)*(m+1)+j-1]+S[(i-1)*m+j-1];
    if(i>=s+2)v=std::max(v,D[(i-2)*(m+1)+j-1]+S[(i-2)*m+j-1]+S[(i-1)*m+j-1]-penalty);
    if(j>=2)v=std::max(v,D[(i-1)*(m+1)+j-2]+.5*(S[(i-1)*m+j-2]+S[(i-1)*m+j-1])-penalty);
    D[i*(m+1)+j]=v;
   }
   if(i-s>=4)out[s*(n+1)+i]=D[i*(m+1)+m]/(i-s);
  }
 }
}
